// n8n hands the Error Trigger one item describing the failed execution.
const e = $json;
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const message = ((e.execution && e.execution.error && e.execution.error.message) || 'no error message').slice(0, 400);
const url = (e.execution && e.execution.url) || '';

// Same job as the agent's `recovery` skill: one short Russian message that says
// what broke, never a stack trace.
const text = [
  '⚠️ Сводка новостей не отправлена.',
  '',
  'Сбой на шаге: ' + node,
  'Причина: ' + message,
  url ? '' : null,
  url ? url : null,
].filter((line) => line !== null).join('\n');

const cfg = $('Config: recovery').first().json;
return [{ json: { text, mcpUrl: cfg.mcpUrl, telegramChatId: cfg.telegramChatId } }];
